// One typed wrapper per Tauri command. Shapes come from src/gen (generated by ts-rs).
import { invoke } from "@tauri-apps/api/core";
import type { AppInfo } from "../gen/AppInfo";
import type { CacheUsageDto } from "../gen/CacheUsageDto";
import type { CategoryDto } from "../gen/CategoryDto";
import type { ChapterPagesDto } from "../gen/ChapterPagesDto";
import type { CmdError } from "../gen/CmdError";
import type { ImportResultDto } from "../gen/ImportResultDto";
import type { LibraryEntryDto } from "../gen/LibraryEntryDto";
import type { MangaDetailDto } from "../gen/MangaDetailDto";
import type { UiSettings } from "../gen/UiSettings";
import type { UiSettingsPatch } from "../gen/UiSettingsPatch";

/** Every command rejects with a CmdError; anything else (IPC failure) is wrapped into one. */
export function toCmdError(e: unknown): CmdError {
  if (e && typeof e === "object" && "kind" in e && "message" in e) {
    const { kind, message } = e as { kind: unknown; message: unknown };
    return { kind: String(kind), message: String(message) };
  }
  return { kind: "internal", message: e instanceof Error ? e.message : String(e) };
}

async function call<T>(cmd: string, args?: Record<string, unknown>): Promise<T> {
  try {
    return await invoke<T>(cmd, args);
  } catch (e) {
    throw toCmdError(e);
  }
}

export const api = {
  appInfo: () => call<AppInfo>("app_info"),
  library: () => call<LibraryEntryDto[]>("library"),
  categories: () => call<CategoryDto[]>("categories"),
  categoryCreate: (name: string) => call<number | null>("category_create", { name }),
  categoryRename: (id: number, name: string) => call<void>("category_rename", { id, name }),
  categoryDelete: (id: number) => call<void>("category_delete", { id }),
  categoryMove: (id: number, up: boolean) => call<void>("category_move", { id, up }),
  mangaSetCategories: (mangaId: number, ids: number[]) =>
    call<void>("manga_set_categories", { mangaId, ids }),
  mangaDetail: (id: number) => call<MangaDetailDto>("manga_detail", { id }),
  rescanLocal: () => call<ImportResultDto>("rescan_local"),
  setViewer: (mangaId: number, viewer: number) => call<void>("set_viewer", { mangaId, viewer }),
  chapterPages: (chapterId: number) => call<ChapterPagesDto>("chapter_pages", { chapterId }),
  saveProgress: (chapterId: number, page: number, total: number) =>
    call<void>("save_progress", { chapterId, page, total }),
  setChapterRead: (chapterId: number, read: boolean) =>
    call<void>("set_chapter_read", { chapterId, read }),
  settingsGet: () => call<UiSettings>("settings_get"),
  settingsSet: (patch: UiSettingsPatch) => call<UiSettings>("settings_set", { patch }),
  cacheUsage: () => call<CacheUsageDto>("cache_usage"),
  cacheClear: () => call<CacheUsageDto>("cache_clear"),
};
